{
  "technical_and_design_decisions": [
    "Implement the YARN info command as an extension of the existing xd-yarn command-line script, querying the established ZooKeeper deployment metadata rather than introducing a new service endpoint.",
    "Implement the Reactor stream processor feature as a module/plugin type whose minimum required configuration is the processor class, with additional settings exposed through established module option metadata and command mechanisms.",
    "Implement history tracking as an opt-in message-enrichment facility that adds stream and module metadata to message headers while preserving existing payloads and remaining compatible with non-history deployments.",
    "Implement Protocol Buffers support as a codec extension using the supported protobuf-java runtime and generated or compatible Message types, with configuration integrated into the existing codec selection mechanism.",
    "Use representative nested and tree-shaped objects, including Protocol Buffer messages, for complex-object performance and compatibility tests.",
    "Implement the Ambari integration as an Ambari management-pack/plugin component that reuses existing Spring XD cluster scripts and service interfaces where possible.",
    "Document and enforce the JDBC partitioning rules: partitionColumn requires tableName and columns, and sql and tableName are mutually exclusive.",
    "Support two mutually exclusive JDBC partitioning modes: sql with an optional where clause, or tableName with an explicit columns definition and partition column.",
    "Use the existing project build, test, packaging, coding conventions, and supported Java version rather than introducing a new build or deployment technology."
  ],
  "assumptions": [
    "The increment targets an existing Spring XD codebase with working YARN deployment, ZooKeeper metadata, module/plugin abstractions, message headers, codec registration, JDBC-HDFS options metadata, and command-line tooling.",
    "The existing APIs are sufficiently extensible that the requested features do not require changes to external Hadoop, YARN, ZooKeeper, Ambari, or messaging products.",
    "The YARN deployment metadata already contains the randomly selected admin port or enough endpoint information to derive it.",
    "Reactor processor modules run in the existing module execution model; this work does not include designing a new runtime, scheduler, or reactive transport.",
    "History tracking is opt-in and does not require persistence beyond the message headers.",
    "Protocol Buffer schemas are supplied by users or test fixtures; this increment does not include a general-purpose .proto compiler service or schema registry.",
    "Ambari support covers provisioning, service lifecycle management, configuration, and basic health/monitoring integration for a supported cluster layout, not every Ambari version or topology.",
    "Documentation work is limited to the relevant wiki/user documentation and examples, without a complete documentation-site redesign.",
    "Existing CI infrastructure and test environments for Java, Hadoop/YARN, ZooKeeper, and the supported messaging components are available.",
    "Effort includes implementation, developer testing, integration testing, code review preparation, and documentation updates, but excludes project management, release coordination, and elapsed waiting time."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment analysis and technical design",
      "activity_description": "Inspect the existing command, module, messaging, codec, JDBC metadata, deployment, and documentation structures; define interfaces, configuration behavior, compatibility constraints, and an implementation plan for all eight user stories.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "YARN deployment info command",
      "activity_description": "Add the info subcommand to xd-yarn, retrieve the current deployment endpoint and admin port from ZooKeeper, format useful deployment information, handle missing or unavailable metadata, and add unit and command-level tests.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Reactor-based stream processor plugin",
      "activity_description": "Implement the Reactor processor module/plugin type with processor-class configuration as the minimum required option, integrate module option metadata and command support for additional configuration, and add processor creation, validation, and integration tests.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A4",
      "activity_name": "Opt-in message history tracking",
      "activity_description": "Add configuration and processing logic to enrich message headers with stream name, module name, and related history metadata; preserve existing behavior when disabled; define header naming and propagation rules; and add unit and pipeline tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "Protocol Buffers codec",
      "activity_description": "Add Protocol Buffer serialization and deserialization support to the codec subsystem, register the codec and its configuration, handle supported message types and errors, update dependencies and packaging, and add round-trip and compatibility tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A6",
      "activity_name": "Complex-object test and performance coverage",
      "activity_description": "Create test fixtures and coverage for Protocol Buffer messages, nested objects, and tree-shaped object graphs; measure serialization/deserialization behavior using repeatable tests; and document the resulting performance characteristics and limitations.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A7",
      "activity_name": "Ambari plugin integration",
      "activity_description": "Implement the Ambari service/plugin artifacts for Spring XD cluster provisioning, configuration, start/stop operations, service checks, and basic monitoring; integrate existing deployment scripts where appropriate; and test installation and lifecycle flows.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A8",
      "activity_name": "JDBC partitioning documentation",
      "activity_description": "Update the wiki and job examples to explain partitioned jobs, the required tableName and columns options, the sql/tableName mutual exclusion rule, and the behavior represented by JdbcHdfsOptionsMetadata.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A9",
      "activity_name": "JDBC partitioning option behavior",
      "activity_description": "Implement or complete validation and execution behavior for the sql-based and tableName-based partitioning modes, including where-clause handling, strict table-column requirements, mutually exclusive options, error messages, and unit/integration tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "Cross-feature integration and regression testing",
      "activity_description": "Run the complete build and test suite, validate interactions with existing modules, codecs, headers, YARN deployment, and JDBC jobs, diagnose regressions, and add missing integration tests across the increment.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A11",
      "activity_name": "Packaging, examples, and delivery preparation",
      "activity_description": "Update build descriptors, dependency and plugin packaging, configuration samples, release notes, and developer-facing examples; perform a clean build and verify that the increment is installable and usable from the supported distributions.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 82
  }
}

